#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;
vector<long long> factorials, inverseFactorials;

long long add_mod(long long a, long long b) {
    return (a + b) % MOD;
}

long long sub_mod(long long a, long long b) {
    return ((a - b) % MOD + MOD) % MOD;
}

long long mul_mod(long long a, long long b) {
    return (a * b) % MOD;
}

long long fast_pow(long long base, long long exp) {
    if (exp == 0) return 1;
    long long half = fast_pow(base, exp / 2);
    if (exp % 2 == 0) return mul_mod(half, half);
    return mul_mod(half, mul_mod(half, base));
}

void setup() {
    int size = 1000000;
    factorials.resize(size);
    inverseFactorials.resize(size);
    factorials[0] = 1;
    for (int i = 1; i < size; i++) {
        factorials[i] = mul_mod(factorials[i - 1], i);
    }
    inverseFactorials[size - 1] = fast_pow(factorials[size - 1], MOD - 2);
    for (int i = size - 2; i >= 0; i--) {
        inverseFactorials[i] = mul_mod(inverseFactorials[i + 1], i + 1);
    }
}

long long calculateCombination(int n, int k) {
    return mul_mod(factorials[n], mul_mod(inverseFactorials[k], inverseFactorials[n - k]));
}

long long computePower(int base, long long exp) {
    long long sum = 0;
    for (int i = 0; i < base; i++) {
        long long term = mul_mod(fast_pow(base - i, exp), calculateCombination(base, i));
        if (i % 2 == 0) {
            sum = add_mod(sum, term);
        } else {
            sum = sub_mod(sum, term);
        }
    }
    return sum;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    setup();
    int n, k;
    try {
        cin >> n >> k;
        if (k == 0) {
            cout << factorials[n] << "\n";
            return 0;
        }
        if (k >= n) {
            cout << 0 << "\n";
            return 0;
        }
        int remaining = n - k;
        long long assignWays = computePower(remaining, n);
        long long pickWays = calculateCombination(n, remaining);
        long long total = mul_mod(assignWays, pickWays);
        cout << mul_mod(total, 2) << "\n";
    } catch (...) {
        cout << 0 << "\n";
    }
    return 0;
}

